content.text:
            for y in neigh:
                if x < y:
                    live[x].add(y)
                    live[y].add(x)
        for x in neigh:
            live[x].discard(v)
        live[v] = set()


def reduce_factors(factors):
    """Divide every potential by its integer gcd (keeps marginals, shrinks Z)."""
    out = []
    for scope, table in factors:
        divisor = 0
        for value in table:
            divisor = gcd(divisor, value)
        if divisor == 0:
            return None
        if divisor > 1:
            table = [value // divisor for value in table]
        out.append((scope, table))
    return out


def _product_table(bucket, allvars, digs, size):
    tab = [1] * size
    positions = {}
    for j, var in enumerate(allvars):
        positions[var] = j
    for scope, table in bucket:
        idxs = [0] * size
        for j, var in enumerate(scope):
            col = digs[positions[var]]
            weight = POW3[j]
            idxs = [ix + dd * weight for ix, dd in zip(idxs, col)]
        tab = [t * table[ix] for t, ix in zip(tab, idxs)]
    return tab


def partition_value(factors, order_vars):
    """Plain bucket elimination; returns the exact partition Z as an int."""
    active = []
    total = 1
    for scope, table in factors:
        if scope:
            active.append((scope, table, -1))
        else:
            total *= table[0]
    for v in order_vars:
        bucket = []
        rest = []
        for item in active:
            if v in item[0]:
                bucket.append(item)
            else:
                rest.append(item)
        if not bucket:
            continue
        scope_set = set()
        for item in bucket:
            scope_set.update(item[0])
        scope_set.discard(v)
        neigh = sorted(scope_set)
        allvars = neigh + [v]
        size = POW3[len(allvars)]
        digs = [[(a // POW3[j]) % 3 for a in range(size)]
                for j in range(len(allvars))]
        tab = _product_table([(s, t) for s, t, _ in bucket], allvars, digs,
                             size)
        step = size // 3
        lam = [tab[n] + tab[n + step] + tab[n + 2 * step] for n in range(step)]
        if neigh:
            rest.append((tuple(neigh), lam, len(active)))
        else:
            total *= lam[0]
        active = rest
    return total


def naive_marginals(factors, order_vars, count):
    """Slow but simple fallback: one specialization per variable and state."""
    marginals = []
    rest_order = []
    for v in range(count):
        rest_order.append([w for w in order_vars if w != v])
    for v in range(count):
        nums = []
        for t in range(3):
            spec = []
            scalar = 1
            for scope, table in factors:
                if v in scope:
                    j = scope.index(v)
                    low = POW3[j]
                    high = POW3[j + 1]
                    out = [0] * POW3[len(scope) - 1]
                    for a, value in enumerate(table):
                        if value and (a // low) % 3 == t:
                            out[(a % low) + (a // high) * low] += value
                    if len(scope) == 1:
                        scalar *= out[0]
                    else:
                        spec.append((tuple(x for x in scope if x != v), out))
                else:
                    spec.append((scope, table))
            nums.append(scalar * partition_value(spec, rest_order[v]))
        marginals.append(nums)
    return marginals


def infer_joint(factors, order_vars, count):
    """Exact joint inference: bucket elimination plus elimination-tree pass.

    Returns (Z, marginals) with marginals[v] the three unnormalized weights.
    """
    m = count
    if m == 0:
        return 1, []
    var_bucket = {}
    for i, v in enumerate(order_vars):
        var_bucket[v] = i
    active = [(scope, table, -1) for scope, table in factors]
    local = [None] * m
    child_msgs = [None] * m
    up_vars = [None] * m
    up_tab = [None] * m
    sep_vars = [None] * m
    sep_tab = [None] * m
    children = [[] for _ in range(m)]

    for i, v in enumerate(order_vars):
        bucket = []
        rest = []
        for item in active:
            if v in item[0]:
                bucket.append(item)
            else:
                rest.append(item)
        scope_set = set()
        for item in bucket:
            scope_set.update(item[0])
        scope_set.discard(v)
        neigh = sorted(scope_set)
        allvars = neigh + [v]
        size = POW3[len(allvars)]
        digs = [[(a // POW3[j]) % 3 for a in range(size)]
                for j in range(len(allvars))]
        tab = _product_table([(s, t) for s, t, _ in bucket], allvars, digs,
                             size)
        step = size // 3
        lam = [tab[n] + tab[n + step] + tab[n + 2 * step] for n in range(step)]
        local[i] = [(s, t) for s, t, src in bucket if src < 0]
        child_msgs[i] = [(src, s, t) for s, t, src in bucket if src >= 0]
        up_vars[i] = allvars
        up_tab[i] = tab
        sep_vars[i] = neigh
        sep_tab[i] = lam
        if neigh:
            rest.append((tuple(neigh), lam, i))
            parent = m
            for x in neigh:
                if var_bucket[x] < parent:
                    parent = var_bucket[x]
            children[parent].append(i)
        active = rest

    # component roots: a bucket without separator is the root of its component
    root_of = [0] * m
    total = 1
    for i in range(m - 1, -1, -1):
        if not sep_vars[i]:
            root_of[i] = i
        else:
            best = m
            for x in sep_vars[i]:
                if var_bucket[x] < best:
                    best = var_bucket[x]
            root_of[i] = root_of[best]
    for i in range(m):
        if not sep_vars[i]:
            total *= sep_tab[i][0]
    if total == 0:
        return 0, None
    scale = [0] * m
    for i in range(m):
        scale[i] = total // sep_tab[root_of[i]][0]

    marginals = [None] * m
    incoming = [None] * m
    for i in range(m - 1, -1, -1):
        allvars = up_vars[i]
        neigh = sep_vars[i]
        step = POW3[len(neigh)]
        tab = up_tab[i]
        msg = incoming[i]
        if msg is None:
            belief = tab
        else:
            belief = [t * msg[a % step] for a, t in enumerate(tab)]
        factor_scale = scale[i]
        marginals[order_vars[i]] = [factor_scale *
                                    sum(belief[t * step:(t + 1) * step])
                                    for t in range(3)]
        kids = children[i]
        if not kids:
            continue
        size = POW3[len(allvars)]
        digs = [[(a // POW3[j]) % 3 for a in range(size)]
                for j in range(len(allvars))]
        positions = {}
        for j, var in enumerate(allvars):
            positions[var] = j
        for j in kids:
            sep_j = sep_vars[j]
            facs = list(local[i])
            for src, fscope, ftable in child_msgs[i]:
                if src != j:
                    facs.append((fscope, ftable))
            send = _product_table(facs, allvars, digs, size)
            if msg is not None:
                send = [t * msg[a % step] for a, t in enumerate(send)]
            out = [0] * POW3[len(sep_j)]
            if sep_j:
                idxs = [0] * size
                for k, var in enumerate(sep_j):
                    col = digs[positions[var]]
                    weight = POW3[k]
                    idxs = [ix + dd * weight for ix, dd in zip(idxs, col)]
                for a, value in enumerate(send):
                    if value:
                        out[idxs[a]] += value
